get_settings.code:
var response = await client.CommonSettings.GetSettingsAsync(
    new Dictionary<string, object?> { ["type"] = "customer_registration_field", ["config_key"] = "abn_placeholder" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var settings = (IReadOnlyDictionary<string, object?>)body["settings"]!;
foreach (var setting in ((IReadOnlyList<object?>)settings["customer_registration_field"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{setting["config_key"]} {setting["value"]}");

